import numpy as np
import pandas as pd

train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(np.float32)
y = train['target'].to_numpy(np.int8)

rng = np.random.default_rng(0)
idx = rng.permutation(len(X))
split = int(len(X)*0.8)
tr, va = idx[:split], idx[split:]
Xtr, Xva = X[tr], X[va]
ytr, yva = y[tr], y[va]

class Node:
    __slots__ = ('feature','threshold','left','right','value')
    def __init__(self, feature=None, threshold=None, left=None, right=None, value=None):
        self.feature = feature
        self.threshold = threshold
        self.left = left
        self.right = right
        self.value = value

def gini(y):
    if len(y) == 0:
        return 0.0
    p = y.mean()
    return 1.0 - p*p - (1-p)*(1-p)

def build(X, y, depth, max_depth, min_leaf, mtry, rng):
    if depth >= max_depth or len(y) <= 2*min_leaf or y.min() == y.max():
        return Node(value=float(y.mean()))
    best = None
    features = rng.choice(X.shape[1], size=mtry, replace=False)
    parent = gini(y)
    for f in features:
        col = X[:, f]
        lo, hi = float(col.min()), float(col.max())
        if lo == hi:
            continue
        thresholds = rng.uniform(lo, hi, size=12)
        for t in thresholds:
            mask = col <= t
            nl = int(mask.sum())
            nr = len(y) - nl
            if nl < min_leaf or nr < min_leaf:
                continue
            gain = parent - (nl/len(y))*gini(y[mask]) - (nr/len(y))*gini(y[~mask])
            if best is None or gain > best[0]:
                best = (gain, f, float(t), mask)
    if best is None or best[0] <= 1e-8:
        return Node(value=float(y.mean()))
    _, f, t, mask = best
    return Node(feature=f, threshold=t,
                left=build(X[mask], y[mask], depth+1, max_depth, min_leaf, mtry, rng),
                right=build(X[~mask], y[~mask], depth+1, max_depth, min_leaf, mtry, rng))

def predict_row(node, row):
    while node.value is None:
        node = node.left if row[node.feature] <= node.threshold else node.right
    return node.value

def forest_predict(Xtr, ytr, Xva, n_trees=100, max_depth=6, min_leaf=20, sample_rate=0.8, mtry=10):
    rng = np.random.default_rng(1)
    preds = np.zeros(len(Xva), dtype=float)
    for _ in range(n_trees):
        sample = rng.integers(0, len(Xtr), size=int(len(Xtr)*sample_rate))
        tree = build(Xtr[sample], ytr[sample], 0, max_depth, min_leaf, mtry, rng)
        preds += np.array([predict_row(tree, row) for row in Xva])
    return (preds / n_trees >= 0.5).astype(np.int8)

for params in [(50,5,20,0.8,10),(100,6,20,0.8,10),(150,6,10,0.8,10),(100,8,10,0.8,15)]:
    pred = forest_predict(Xtr,ytr,Xva,*params)
    print(params, (pred==yva).mean())
