import numpy as np
import pandas as pd

train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(float)
y = train['target'].to_numpy(int)

# greedy 2-level tree over linear/sq/abs features and quantile thresholds
transforms = {
    'linear': lambda a: a,
    'sq': lambda a: a**2,
    'abs': lambda a: np.abs(a),
}

class Leaf:
    def __init__(self, value):
        self.value = int(value)
        self.left = None
        self.right = None

class Node:
    def __init__(self, name, j, t, left, right):
        self.name, self.j, self.t = name, j, t
        self.left, self.right = left, right

def best_split(X, y):
    best = None
    for name, fn in transforms.items():
        Z = fn(X)
        for j in range(Z.shape[1]):
            for t in np.unique(np.quantile(Z[:, j], np.linspace(0.1, 0.9, 17))):
                mask = Z[:, j] <= t
                if mask.sum() < 50 or (~mask).sum() < 50:
                    continue
                left = y[mask]
                right = y[~mask]
                lp = int(left.mean() >= 0.5)
                rp = int(right.mean() >= 0.5)
                acc = (np.where(mask, lp, rp) == y).mean()
                if best is None or acc > best[0]:
                    best = (acc, name, j, float(t), mask)
    return best

def train_depth2(X, y):
    root = best_split(X, y)
    _, name, j, t, mask = root
    left_leaf = Leaf(int(y[mask].mean() >= 0.5))
    right_leaf = Leaf(int(y[~mask].mean() >= 0.5))
    # try one extra split on each side
    for side, side_mask in [('left', mask), ('right', ~mask)]:
        if side_mask.sum() < 200:
            continue
        child = best_split(X[side_mask], y[side_mask])
        if child is None:
            continue
        _, cname, cj, ct, cmask = child
        local_y = y[side_mask]
        lpred = int(local_y[cmask].mean() >= 0.5)
        rpred = int(local_y[~cmask].mean() >= 0.5)
        node = Node(cname, cj, ct, Leaf(lpred), Leaf(rpred))
        if side == 'left':
            left_leaf = node
        else:
            right_leaf = node
    return Node(name, j, t, left_leaf, right_leaf)

def predict_one(node, row):
    while isinstance(node, Node):
        z = row[node.j]
        if node.name == 'sq':
            z = z * z
        elif node.name == 'abs':
            z = abs(z)
        node = node.left if z <= node.t else node.right
    return node.value

def predict(model, X):
    return np.array([predict_one(model, row) for row in X])

rng = np.random.default_rng(0)
idx = rng.permutation(len(X))
parts = np.array_split(idx, 5)
scores = []
for fold in range(5):
    va = parts[fold]
    tr = np.concatenate([parts[i] for i in range(5) if i != fold])
    model = train_depth2(X[tr], y[tr])
    pred = predict(model, X[va])
    score = (pred == y[va]).mean()
    scores.append(score)
    print('fold', fold, 'acc', score)
print('mean', float(np.mean(scores)))
